package io.github.charlietap.chasm.executor.invoker.dispatch.memory

import io.github.charlietap.chasm.runtime.dispatch.DispatchableInstruction
import io.github.charlietap.chasm.runtime.instruction.MemoryInstruction

fun MemoryInstructionDispatcher(
    instruction: MemoryInstruction,
): DispatchableInstruction = when (instruction) {
    is MemoryInstruction.I32LoadI -> I32LoadIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32LoadS -> I32LoadSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64LoadI -> I64LoadIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64LoadS -> I64LoadSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32LoadI -> F32LoadIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32LoadS -> F32LoadSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64LoadI -> F64LoadIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64LoadS -> F64LoadSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load8SI -> I32Load8SIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load8SS -> I32Load8SSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load8UI -> I32Load8UIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load8US -> I32Load8USDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load16SI -> I32Load16SIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load16SS -> I32Load16SSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load16UI -> I32Load16UIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Load16US -> I32Load16USDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load8SI -> I64Load8SIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load8SS -> I64Load8SSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load8UI -> I64Load8UIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load8US -> I64Load8USDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load16SI -> I64Load16SIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load16SS -> I64Load16SSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load16UI -> I64Load16UIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load16US -> I64Load16USDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load32SI -> I64Load32SIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load32SS -> I64Load32SSDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load32UI -> I64Load32UIDispatcher(instruction.address, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Load32US -> I64Load32USDispatcher(instruction.addressSlot, instruction.destinationSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.MemorySizeS -> MemorySizeSDispatcher(instruction.destinationSlot, instruction.memory)
    is MemoryInstruction.MemoryGrowI -> MemoryGrowIDispatcher(instruction.pagesToAdd, instruction.destinationSlot, instruction.memory)
    is MemoryInstruction.MemoryGrowS -> MemoryGrowSDispatcher(instruction.pagesToAddSlot, instruction.destinationSlot, instruction.memory)
    is MemoryInstruction.MemoryInitIii -> MemoryInitIiiDispatcher(instruction.bytesToCopy, instruction.sourceOffset, instruction.destinationOffset, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitIis -> MemoryInitIisDispatcher(instruction.bytesToCopy, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitIsi -> MemoryInitIsiDispatcher(instruction.bytesToCopy, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitIss -> MemoryInitIssDispatcher(instruction.bytesToCopy, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitSii -> MemoryInitSiiDispatcher(instruction.bytesToCopySlot, instruction.sourceOffset, instruction.destinationOffset, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitSis -> MemoryInitSisDispatcher(instruction.bytesToCopySlot, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitSsi -> MemoryInitSsiDispatcher(instruction.bytesToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryInitSss -> MemoryInitSssDispatcher(instruction.bytesToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.memory, instruction.data)
    is MemoryInstruction.MemoryCopyIii -> MemoryCopyIiiDispatcher(instruction.bytesToCopy, instruction.sourceOffset, instruction.destinationOffset, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopyIis -> MemoryCopyIisDispatcher(instruction.bytesToCopy, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopyIsi -> MemoryCopyIsiDispatcher(instruction.bytesToCopy, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopyIss -> MemoryCopyIssDispatcher(instruction.bytesToCopy, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopySii -> MemoryCopySiiDispatcher(instruction.bytesToCopySlot, instruction.sourceOffset, instruction.destinationOffset, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopySis -> MemoryCopySisDispatcher(instruction.bytesToCopySlot, instruction.sourceOffset, instruction.destinationOffsetSlot, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopySsi -> MemoryCopySsiDispatcher(instruction.bytesToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffset, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryCopySss -> MemoryCopySssDispatcher(instruction.bytesToCopySlot, instruction.sourceOffsetSlot, instruction.destinationOffsetSlot, instruction.srcMemory, instruction.dstMemory)
    is MemoryInstruction.MemoryFillIii -> MemoryFillIiiDispatcher(instruction.bytesToFill, instruction.fillValue, instruction.offset, instruction.memory)
    is MemoryInstruction.MemoryFillIis -> MemoryFillIisDispatcher(instruction.bytesToFill, instruction.fillValue, instruction.offsetSlot, instruction.memory)
    is MemoryInstruction.MemoryFillIsi -> MemoryFillIsiDispatcher(instruction.bytesToFill, instruction.fillValueSlot, instruction.offset, instruction.memory)
    is MemoryInstruction.MemoryFillIss -> MemoryFillIssDispatcher(instruction.bytesToFill, instruction.fillValueSlot, instruction.offsetSlot, instruction.memory)
    is MemoryInstruction.MemoryFillSii -> MemoryFillSiiDispatcher(instruction.bytesToFillSlot, instruction.fillValue, instruction.offset, instruction.memory)
    is MemoryInstruction.MemoryFillSis -> MemoryFillSisDispatcher(instruction.bytesToFillSlot, instruction.fillValue, instruction.offsetSlot, instruction.memory)
    is MemoryInstruction.MemoryFillSsi -> MemoryFillSsiDispatcher(instruction.bytesToFillSlot, instruction.fillValueSlot, instruction.offset, instruction.memory)
    is MemoryInstruction.MemoryFillSss -> MemoryFillSssDispatcher(instruction.bytesToFillSlot, instruction.fillValueSlot, instruction.offsetSlot, instruction.memory)
    is MemoryInstruction.I32StoreIi -> I32StoreIiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32StoreIs -> I32StoreIsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32StoreSi -> I32StoreSiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32StoreSs -> I32StoreSsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64StoreIi -> I64StoreIiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64StoreIs -> I64StoreIsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64StoreSi -> I64StoreSiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64StoreSs -> I64StoreSsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32StoreIi -> F32StoreIiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32StoreIs -> F32StoreIsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32StoreSi -> F32StoreSiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F32StoreSs -> F32StoreSsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64StoreIi -> F64StoreIiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64StoreIs -> F64StoreIsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64StoreSi -> F64StoreSiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.F64StoreSs -> F64StoreSsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store8Ii -> I32Store8IiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store8Is -> I32Store8IsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store8Si -> I32Store8SiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store8Ss -> I32Store8SsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store16Ii -> I32Store16IiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store16Is -> I32Store16IsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store16Si -> I32Store16SiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I32Store16Ss -> I32Store16SsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store8Ii -> I64Store8IiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store8Is -> I64Store8IsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store8Si -> I64Store8SiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store8Ss -> I64Store8SsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store16Ii -> I64Store16IiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store16Is -> I64Store16IsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store16Si -> I64Store16SiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store16Ss -> I64Store16SsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store32Ii -> I64Store32IiDispatcher(instruction.value, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store32Is -> I64Store32IsDispatcher(instruction.value, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store32Si -> I64Store32SiDispatcher(instruction.valueSlot, instruction.address, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.I64Store32Ss -> I64Store32SsDispatcher(instruction.valueSlot, instruction.addressSlot, instruction.memory, instruction.memArg.offset)
    is MemoryInstruction.DataDrop -> DataDropDispatcher(instruction.data)
}
